import React, { useState } from 'react';
import {
  Box,
  Button,
  TextField,
  Typography,
  Paper,
  IconButton,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  FormControlLabel,
  Checkbox,
  SelectChangeEvent,
  Grid,
  useTheme,
  useMediaQuery,
  Tooltip,
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import AddIcon from '@mui/icons-material/Add';
import { Entity, Field } from '../../types';
import { useEntity } from '../../contexts/EntityContext';

interface EntityEditorProps {
  onEntityCreated: (entity: Entity) => void;
}

const FIELD_TYPES = ['string', 'number', 'boolean', 'array', 'object'] as const;

const initialField: Field = {
  name: '',
  type: 'string',
  required: false,
  description: '',
};

export default function EntityEditor({ onEntityCreated }: EntityEditorProps) {
  const { addEntity } = useEntity();
  const [entityName, setEntityName] = useState('');
  const [fields, setFields] = useState<Field[]>([]);
  const [currentField, setCurrentField] = useState<Field>(initialField);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const handleAddField = () => {
    if (currentField.name) {
      setFields([...fields, currentField]);
      setCurrentField(initialField);
    }
  };

  const handleDeleteField = (index: number) => {
    setFields(fields.filter((_, i) => i !== index));
  };

  const handleSaveEntity = () => {
    if (entityName && fields.length > 0) {
      const newEntity: Entity = {
        name: entityName,
        fields,
        endpoints: [],
      };
      addEntity(newEntity);
      onEntityCreated(newEntity);
      setEntityName('');
      setFields([]);
    }
  };

  return (
    <Box sx={{ p: isMobile ? 2 : 3 }}>
      <Typography variant="h5" gutterBottom>
        Create New Entity
      </Typography>
      
      <Paper elevation={3} sx={{ p: isMobile ? 2 : 3, mb: 3 }}>
        <Grid container spacing={3}>
          <Grid item xs={12}>
            <TextField
              fullWidth
              label="Entity Name"
              value={entityName}
              onChange={(e: React.ChangeEvent<HTMLInputElement>) => setEntityName(e.target.value)}
              variant="outlined"
              placeholder="e.g., Person, Product, Order"
            />
          </Grid>

          <Grid item xs={12}>
            <Typography variant="h6" gutterBottom color="primary">
              Add Field
            </Typography>
            
            <Grid container spacing={2} alignItems="center">
              <Grid item xs={12} sm={4}>
                <TextField
                  fullWidth
                  label="Field Name"
                  value={currentField.name}
                  onChange={(e: React.ChangeEvent<HTMLInputElement>) => 
                    setCurrentField({ ...currentField, name: e.target.value })
                  }
                  placeholder="e.g., name, email, age"
                />
              </Grid>
              
              <Grid item xs={12} sm={3}>
                <FormControl fullWidth>
                  <InputLabel>Type</InputLabel>
                  <Select
                    value={currentField.type}
                    label="Type"
                    onChange={(e: SelectChangeEvent) =>
                      setCurrentField({ ...currentField, type: e.target.value as Field['type'] })
                    }
                  >
                    {FIELD_TYPES.map((type) => (
                      <MenuItem key={type} value={type}>
                        {type}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>
              
              <Grid item xs={12} sm={3}>
                <TextField
                  fullWidth
                  label="Description"
                  value={currentField.description}
                  onChange={(e: React.ChangeEvent<HTMLInputElement>) =>
                    setCurrentField({ ...currentField, description: e.target.value })
                  }
                  placeholder="Field description"
                />
              </Grid>

              <Grid item xs={6} sm={1}>
                <FormControlLabel
                  control={
                    <Checkbox
                      checked={currentField.required}
                      onChange={(e: React.ChangeEvent<HTMLInputElement>) => 
                        setCurrentField({ ...currentField, required: e.target.checked })
                      }
                    />
                  }
                  label="Required"
                />
              </Grid>
              
              <Grid item xs={6} sm={1}>
                <Tooltip title="Add Field">
                  <Button
                    variant="contained"
                    onClick={handleAddField}
                    disabled={!currentField.name}
                    sx={{ 
                      minWidth: 0,
                      width: '40px',
                      height: '40px',
                      borderRadius: '50%',
                      p: 0
                    }}
                  >
                    <AddIcon />
                  </Button>
                </Tooltip>
              </Grid>
            </Grid>
          </Grid>

          {fields.length > 0 && (
            <Grid item xs={12}>
              <Typography variant="h6" gutterBottom color="primary" sx={{ mt: 2 }}>
                Fields
              </Typography>
              
              {fields.map((field, index) => (
                <Paper
                  key={index}
                  sx={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 2,
                    mb: 1,
                    p: 2,
                    bgcolor: 'background.default',
                    flexWrap: isMobile ? 'wrap' : 'nowrap',
                  }}
                >
                  <Box sx={{ flexGrow: 1 }}>
                    <Typography variant="subtitle1" sx={{ fontWeight: 500 }}>
                      {field.name} {field.required && '*'}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Type: {field.type}
                      {field.description && ` • ${field.description}`}
                    </Typography>
                  </Box>
                  <IconButton 
                    onClick={() => handleDeleteField(index)} 
                    color="error"
                    size="small"
                  >
                    <DeleteIcon />
                  </IconButton>
                </Paper>
              ))}
            </Grid>
          )}

          <Grid item xs={12}>
            <Button
              variant="contained"
              color="primary"
              onClick={handleSaveEntity}
              disabled={!entityName || fields.length === 0}
              fullWidth={isMobile}
              sx={{ mt: 2 }}
            >
              Save Entity
            </Button>
          </Grid>
        </Grid>
      </Paper>
    </Box>
  );
}
