import React, { useState } from 'react';
import {
  Box,
  Button,
  Paper,
  Typography,
  ButtonGroup,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  useTheme,
  useMediaQuery,
  IconButton,
} from '@mui/material';
import {
  Visibility as PreviewIcon,
  Download as DownloadIcon,
  Close as CloseIcon,
} from '@mui/icons-material';
import { useEntity } from '../../contexts/EntityContext';
import { Entity } from '../../types';
import { stringify } from 'yaml';

function generateSwaggerSpec(entities: Entity[]) {
  const paths: Record<string, any> = {};
  const schemas: Record<string, any> = {};

  entities.forEach((entity) => {
    schemas[entity.name] = {
      type: 'object',
      properties: entity.fields.reduce((acc, field) => {
        acc[field.name] = {
          type: field.type,
          description: field.description || undefined,
        };
        return acc;
      }, {} as Record<string, any>),
      required: entity.fields
        .filter((field) => field.required)
        .map((field) => field.name),
    };

    entity.endpoints.forEach((endpoint) => {
      const path = endpoint.path;
      if (!paths[path]) {
        paths[path] = {};
      }

      paths[path][endpoint.method.toLowerCase()] = {
        summary: endpoint.description,
        tags: [entity.name],
        responses: endpoint.responses,
      };

      if (endpoint.requestBody) {
        paths[path][endpoint.method.toLowerCase()].requestBody = {
          content: {
            'application/json': {
              schema: {
                $ref: `#/components/schemas/${entity.name}`,
              },
            },
          },
        };
      }
    });
  });

  const spec = {
    openapi: '3.0.0',
    info: {
      title: 'Generated API Specification',
      version: '1.0.0',
      description: 'API specification generated using Sheep API Spec Builder',
    },
    paths,
    components: {
      schemas,
    },
  };

  return spec;
}

export default function SwaggerGenerator() {
  const { entities } = useEntity();
  const [previewOpen, setPreviewOpen] = useState(false);
  const [previewFormat, setPreviewFormat] = useState<'json' | 'yaml'>('json');
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const handlePreview = (format: 'json' | 'yaml') => {
    setPreviewFormat(format);
    setPreviewOpen(true);
  };

  const handleDownload = (format: 'json' | 'yaml') => {
    const spec = generateSwaggerSpec(entities);
    let content: string;
    let mimeType: string;
    let extension: string;

    if (format === 'json') {
      content = JSON.stringify(spec, null, 2);
      mimeType = 'application/json';
      extension = 'json';
    } else {
      content = stringify(spec);
      mimeType = 'application/yaml';
      extension = 'yaml';
    }

    const blob = new Blob([content], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `openapi-spec.${extension}`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const getPreviewContent = () => {
    const spec = generateSwaggerSpec(entities);
    return previewFormat === 'json'
      ? JSON.stringify(spec, null, 2)
      : stringify(spec);
  };

  return (
    <Box sx={{ p: isMobile ? 2 : 3 }}>
      <Typography variant="h5" gutterBottom>
        Generate OpenAPI Specification
      </Typography>

      <Paper elevation={3} sx={{ p: isMobile ? 2 : 3, mb: 3 }}>
        <Typography variant="body1" gutterBottom sx={{ mb: 3 }}>
          Preview or download your OpenAPI 3.0 specification in JSON or YAML format.
        </Typography>

        <Box sx={{ display: 'flex', flexDirection: isMobile ? 'column' : 'row', gap: 2 }}>
          <Box>
            <Typography variant="subtitle2" gutterBottom color="primary">
              Preview
            </Typography>
            <ButtonGroup variant="outlined" disabled={entities.length === 0}>
              <Button
                startIcon={<PreviewIcon />}
                onClick={() => handlePreview('json')}
              >
                JSON
              </Button>
              <Button
                startIcon={<PreviewIcon />}
                onClick={() => handlePreview('yaml')}
              >
                YAML
              </Button>
            </ButtonGroup>
          </Box>

          <Box>
            <Typography variant="subtitle2" gutterBottom color="primary">
              Download
            </Typography>
            <ButtonGroup variant="contained" disabled={entities.length === 0}>
              <Button
                startIcon={<DownloadIcon />}
                onClick={() => handleDownload('json')}
              >
                JSON
              </Button>
              <Button
                startIcon={<DownloadIcon />}
                onClick={() => handleDownload('yaml')}
              >
                YAML
              </Button>
            </ButtonGroup>
          </Box>
        </Box>

        {entities.length === 0 && (
          <Typography color="text.secondary" sx={{ mt: 2 }}>
            Please define at least one entity before generating the specification.
          </Typography>
        )}
      </Paper>

      <Dialog
        open={previewOpen}
        onClose={() => setPreviewOpen(false)}
        maxWidth="md"
        fullWidth
        fullScreen={isMobile}
      >
        <DialogTitle sx={{ 
          m: 0, 
          p: 2, 
          display: 'flex', 
          justifyContent: 'space-between', 
          alignItems: 'center'
        }}>
          <Typography variant="h6">
            Preview ({previewFormat.toUpperCase()})
          </Typography>
          <IconButton
            aria-label="close"
            onClick={() => setPreviewOpen(false)}
            sx={{ color: 'grey.500' }}
          >
            <CloseIcon />
          </IconButton>
        </DialogTitle>
        <DialogContent dividers>
          <pre style={{ 
            margin: 0,
            whiteSpace: 'pre-wrap',
            wordWrap: 'break-word',
            fontFamily: 'monospace',
            fontSize: '14px',
            backgroundColor: '#f5f5f7',
            padding: '16px',
            borderRadius: '8px',
          }}>
            {getPreviewContent()}
          </pre>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setPreviewOpen(false)} color="primary">
            Close
          </Button>
          <Button
            onClick={() => handleDownload(previewFormat)}
            variant="contained"
            color="primary"
            startIcon={<DownloadIcon />}
          >
            Download
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}
