import React, { useState } from 'react';
import {
  ThemeProvider,
  createTheme,
  Box,
  AppBar,
  Toolbar,
  Typography,
  Tabs,
  Tab,
  Container,
  useMediaQuery,
  useTheme,
} from '@mui/material';
import { EntityProvider, useEntity } from './contexts/EntityContext';
import EntityEditor from './components/EntityEditor/EntityEditor';
import EndpointEditor from './components/EndpointEditor/EndpointEditor';
import SwaggerGenerator from './components/SwaggerGenerator/SwaggerGenerator';
import { Entity } from './types';

const theme = createTheme({
  palette: {
    primary: {
      main: '#007AFF', // Apple's blue
      light: '#5856D6',
      dark: '#0055FF',
    },
    secondary: {
      main: '#5856D6', // Apple's purple
    },
    background: {
      default: '#F5F5F7', // Apple's light gray
      paper: '#FFFFFF',
    },
  },
  typography: {
    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif',
    h5: {
      fontWeight: 600,
    },
    h6: {
      fontWeight: 600,
    },
  },
  components: {
    MuiAppBar: {
      styleOverrides: {
        root: {
          backgroundColor: 'rgba(255, 255, 255, 0.8)',
          backdropFilter: 'blur(10px)',
          boxShadow: 'none',
          borderBottom: '1px solid rgba(0, 0, 0, 0.1)',
        },
      },
    },
    MuiButton: {
      styleOverrides: {
        root: {
          borderRadius: 8,
          textTransform: 'none',
          fontSize: '0.95rem',
          padding: '8px 16px',
        },
        contained: {
          boxShadow: 'none',
          '&:hover': {
            boxShadow: 'none',
          },
        },
      },
    },
    MuiPaper: {
      styleOverrides: {
        root: {
          borderRadius: 12,
          boxShadow: '0 2px 12px rgba(0, 0, 0, 0.1)',
        },
      },
    },
  },
});

interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

function TabPanel(props: TabPanelProps) {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`tabpanel-${index}`}
      aria-labelledby={`tab-${index}`}
      {...other}
    >
      {value === index && <Box>{children}</Box>}
    </div>
  );
}

function MainContent() {
  const [tabIndex, setTabIndex] = useState(0);
  const [selectedEntity, setSelectedEntity] = useState<Entity | null>(null);
  const { entities, updateEntity } = useEntity();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const handleTabChange = (_event: React.SyntheticEvent, newValue: number) => {
    setTabIndex(newValue);
  };

  const handleEntityCreated = (entity: Entity) => {
    setSelectedEntity(entity);
    setTabIndex(1);
  };

  const handleEndpointsSave = (endpoints: any[]) => {
    if (selectedEntity) {
      const updatedEntity = {
        ...selectedEntity,
        endpoints,
      };
      const entityIndex = entities.findIndex(e => e.name === selectedEntity.name);
      if (entityIndex !== -1) {
        updateEntity(entityIndex, updatedEntity);
        setSelectedEntity(updatedEntity);
      }
      setTabIndex(2);
    }
  };

  return (
    <Box sx={{ flexGrow: 1, height: '100vh', display: 'flex', flexDirection: 'column' }}>
      <AppBar position="fixed">
        <Toolbar>
          <Typography 
            variant="h6" 
            component="div" 
            sx={{ 
              flexGrow: 1, 
              color: 'primary.main',
              fontWeight: 'bold',
              fontSize: isMobile ? '1.1rem' : '1.3rem'
            }}
          >
            Sheep API Spec Builder
          </Typography>
        </Toolbar>
        <Tabs 
          value={tabIndex} 
          onChange={handleTabChange}
          variant={isMobile ? "scrollable" : "standard"}
          scrollButtons={isMobile ? "auto" : false}
          sx={{ 
            backgroundColor: 'background.paper',
            px: 2,
            '& .MuiTab-root': {
              minHeight: 48,
              fontSize: isMobile ? '0.8rem' : '0.9rem',
            }
          }}
        >
          <Tab label="Entity Definition" />
          <Tab 
            label="Endpoint Configuration" 
            disabled={!selectedEntity}
          />
          <Tab 
            label="Generate Swagger" 
            disabled={!entities.length}
          />
        </Tabs>
      </AppBar>

      <Container 
        maxWidth="lg" 
        sx={{ 
          flexGrow: 1, 
          mt: '112px', // Height of AppBar + Tabs
          mb: 3,
          overflow: 'auto'
        }}
      >
        <TabPanel value={tabIndex} index={0}>
          <EntityEditor onEntityCreated={handleEntityCreated} />
        </TabPanel>
        <TabPanel value={tabIndex} index={1}>
          {selectedEntity && (
            <EndpointEditor
              entity={selectedEntity}
              onSave={handleEndpointsSave}
            />
          )}
        </TabPanel>
        <TabPanel value={tabIndex} index={2}>
          <SwaggerGenerator />
        </TabPanel>
      </Container>
    </Box>
  );
}

function App() {
  return (
    <ThemeProvider theme={theme}>
      <EntityProvider>
        <MainContent />
      </EntityProvider>
    </ThemeProvider>
  );
}

export default App;
