import React, { useState } from 'react';
import {
  Box,
  Button,
  TextField,
  Typography,
  Paper,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  SelectChangeEvent,
  Grid,
  IconButton,
  useTheme,
  useMediaQuery,
  Tooltip,
  Chip,
} from '@mui/material';
import {
  Delete as DeleteIcon,
  Add as AddIcon,
  AutoFixHigh as GenerateIcon,
} from '@mui/icons-material';
import { Entity, Endpoint } from '../../types';

interface EndpointEditorProps {
  entity: Entity;
  onSave: (endpoints: Endpoint[]) => void;
}

const HTTP_METHODS = ['GET', 'POST', 'PUT', 'DELETE'] as const;

const initialEndpoint: Endpoint = {
  path: '',
  method: 'GET',
  description: '',
  responses: {
    '200': {
      description: 'Successful operation',
    },
  },
};

export default function EndpointEditor({ entity, onSave }: EndpointEditorProps) {
  const [endpoints, setEndpoints] = useState<Endpoint[]>(entity.endpoints);
  const [currentEndpoint, setCurrentEndpoint] = useState<Endpoint>(initialEndpoint);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const handleAddEndpoint = () => {
    if (currentEndpoint.path) {
      setEndpoints([...endpoints, currentEndpoint]);
      setCurrentEndpoint(initialEndpoint);
    }
  };

  const handleDeleteEndpoint = (index: number) => {
    setEndpoints(endpoints.filter((_, i) => i !== index));
  };

  const handleSave = () => {
    onSave(endpoints);
  };

  const defaultEndpoints = () => {
    const basePath = `/${entity.name.toLowerCase()}`;
    const newEndpoints: Endpoint[] = [
      {
        path: basePath,
        method: 'GET',
        description: `Get all ${entity.name}s`,
        responses: {
          '200': { description: `List of ${entity.name}s` },
        },
      },
      {
        path: `${basePath}/{id}`,
        method: 'GET',
        description: `Get ${entity.name} by ID`,
        responses: {
          '200': { description: `${entity.name} found` },
          '404': { description: 'Not found' },
        },
      },
      {
        path: basePath,
        method: 'POST',
        description: `Create a new ${entity.name}`,
        requestBody: true,
        responses: {
          '201': { description: `${entity.name} created` },
          '400': { description: 'Invalid input' },
        },
      },
      {
        path: `${basePath}/{id}`,
        method: 'PUT',
        description: `Update ${entity.name}`,
        requestBody: true,
        responses: {
          '200': { description: `${entity.name} updated` },
          '404': { description: 'Not found' },
          '400': { description: 'Invalid input' },
        },
      },
      {
        path: `${basePath}/{id}`,
        method: 'DELETE',
        description: `Delete ${entity.name}`,
        responses: {
          '204': { description: `${entity.name} deleted` },
          '404': { description: 'Not found' },
        },
      },
    ];
    setEndpoints(newEndpoints);
  };

  const getMethodColor = (method: string) => {
    switch (method) {
      case 'GET': return '#61affe';
      case 'POST': return '#49cc90';
      case 'PUT': return '#fca130';
      case 'DELETE': return '#f93e3e';
      default: return theme.palette.primary.main;
    }
  };

  return (
    <Box sx={{ p: isMobile ? 2 : 3 }}>
      <Typography variant="h5" gutterBottom>
        Configure Endpoints for {entity.name}
      </Typography>

      <Paper elevation={3} sx={{ p: isMobile ? 2 : 3, mb: 3 }}>
        <Grid container spacing={3}>
          <Grid item xs={12}>
            <Button
              variant="outlined"
              startIcon={<GenerateIcon />}
              onClick={defaultEndpoints}
              sx={{ mb: 3 }}
            >
              Generate Default CRUD Endpoints
            </Button>
          </Grid>

          <Grid item xs={12}>
            <Typography variant="h6" gutterBottom color="primary">
              Add Endpoint
            </Typography>
            
            <Grid container spacing={2} alignItems="center">
              <Grid item xs={12} sm={4}>
                <TextField
                  fullWidth
                  label="Path"
                  value={currentEndpoint.path}
                  onChange={(e) => setCurrentEndpoint({ ...currentEndpoint, path: e.target.value })}
                  placeholder={`/${entity.name.toLowerCase()}`}
                />
              </Grid>
              
              <Grid item xs={12} sm={3}>
                <FormControl fullWidth>
                  <InputLabel>Method</InputLabel>
                  <Select
                    value={currentEndpoint.method}
                    label="Method"
                    onChange={(e: SelectChangeEvent) =>
                      setCurrentEndpoint({
                        ...currentEndpoint,
                        method: e.target.value as Endpoint['method'],
                      })
                    }
                  >
                    {HTTP_METHODS.map((method) => (
                      <MenuItem key={method} value={method}>
                        {method}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>
              
              <Grid item xs={12} sm={4}>
                <TextField
                  fullWidth
                  label="Description"
                  value={currentEndpoint.description}
                  onChange={(e) =>
                    setCurrentEndpoint({ ...currentEndpoint, description: e.target.value })
                  }
                  placeholder="Endpoint description"
                />
              </Grid>
              
              <Grid item xs={12} sm={1}>
                <Tooltip title="Add Endpoint">
                  <Button
                    variant="contained"
                    onClick={handleAddEndpoint}
                    disabled={!currentEndpoint.path}
                    sx={{ 
                      minWidth: 0,
                      width: '40px',
                      height: '40px',
                      borderRadius: '50%',
                      p: 0
                    }}
                  >
                    <AddIcon />
                  </Button>
                </Tooltip>
              </Grid>
            </Grid>
          </Grid>

          {endpoints.length > 0 && (
            <Grid item xs={12}>
              <Typography variant="h6" gutterBottom color="primary" sx={{ mt: 2 }}>
                Defined Endpoints
              </Typography>
              
              {endpoints.map((endpoint, index) => (
                <Paper
                  key={index}
                  sx={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 2,
                    mb: 1,
                    p: 2,
                    bgcolor: 'background.default',
                    flexWrap: isMobile ? 'wrap' : 'nowrap',
                  }}
                >
                  <Box sx={{ flexGrow: 1 }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                      <Chip
                        label={endpoint.method}
                        size="small"
                        sx={{
                          bgcolor: getMethodColor(endpoint.method),
                          color: 'white',
                          fontWeight: 'bold',
                        }}
                      />
                      <Typography variant="subtitle1" sx={{ fontWeight: 500 }}>
                        {endpoint.path}
                      </Typography>
                    </Box>
                    <Typography variant="body2" color="text.secondary">
                      {endpoint.description}
                    </Typography>
                  </Box>
                  <IconButton 
                    onClick={() => handleDeleteEndpoint(index)} 
                    color="error"
                    size="small"
                  >
                    <DeleteIcon />
                  </IconButton>
                </Paper>
              ))}
            </Grid>
          )}

          <Grid item xs={12}>
            <Button
              variant="contained"
              color="primary"
              onClick={handleSave}
              disabled={endpoints.length === 0}
              fullWidth={isMobile}
              sx={{ mt: 2 }}
            >
              Save Endpoints
            </Button>
          </Grid>
        </Grid>
      </Paper>
    </Box>
  );
}
