import React, { createContext, useContext, useState } from 'react';
import { Entity } from '../types';

interface EntityContextType {
  entities: Entity[];
  addEntity: (entity: Entity) => void;
  updateEntity: (index: number, entity: Entity) => void;
  deleteEntity: (index: number) => void;
}

const EntityContext = createContext<EntityContextType | undefined>(undefined);

export function EntityProvider({ children }: { children: React.ReactNode }) {
  const [entities, setEntities] = useState<Entity[]>([]);

  const addEntity = (entity: Entity) => {
    setEntities([...entities, entity]);
  };

  const updateEntity = (index: number, entity: Entity) => {
    const newEntities = [...entities];
    newEntities[index] = entity;
    setEntities(newEntities);
  };

  const deleteEntity = (index: number) => {
    const newEntities = entities.filter((_, i) => i !== index);
    setEntities(newEntities);
  };

  return (
    <EntityContext.Provider value={{ entities, addEntity, updateEntity, deleteEntity }}>
      {children}
    </EntityContext.Provider>
  );
}

export function useEntity() {
  const context = useContext(EntityContext);
  if (context === undefined) {
    throw new Error('useEntity must be used within an EntityProvider');
  }
  return context;
}
